package com.yonlab.vision;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class AnalyticsPhase2Test {
 private Observations.Face face(float yaw,float pitch,float eyes){Observations.Face f=new Observations.Face(.1f,.1f,.8f,.9f);f.trackingId=8;f.yaw=yaw;f.pitch=pitch;f.leftEye=f.rightEye=eyes;return f;}
 private Observations.Detection person(float x){return new Observations.Detection(0,"person",.9f,x-.07f,.2f,x+.07f,.7f);}
 @Test public void calibrationUsesRealFiniteNeutralAnglesAndClearRemovesOffsets(){Analytics.Drive a=new Analytics.Drive();assertFalse(a.calibrate());a.update(List.of(face(35,15,1)),0);assertTrue(a.calibrate());Analytics.DriveSnapshot s=a.update(List.of(face(40,18,1)),100);assertEquals(5,s.yaw,.001);assertEquals(3,s.pitch,.001);assertEquals(40,s.rawYaw,.001);assertTrue(s.calibrated);a.resetCalibration();assertEquals(40,a.snapshot().yaw,.001);assertFalse(a.snapshot().calibrated);}
 @Test public void calibrationWrapsEulerBoundaryAndMissingAngleCannotCalibrate(){Analytics.Drive a=new Analytics.Drive();a.update(List.of(face(179,0,1)),0);assertTrue(a.calibrate());assertEquals(2,a.update(List.of(face(-179,0,1)),100).yaw,.001);a.update(List.of(face(Float.NaN,0,1)),200);assertFalse(a.calibrate());}
 @Test public void calibratedPoseStillRequiresRealSustainedOffset(){Analytics.Drive a=new Analytics.Drive();a.update(List.of(face(35,15,1)),0);a.calibrate();assertFalse(a.update(List.of(face(35,15,1)),1000).lookingAway);a.update(List.of(face(70,15,1)),1100);assertFalse(a.update(List.of(face(70,15,1)),1899).lookingAway);assertTrue(a.update(List.of(face(70,15,1)),1900).lookingAway);}
 @Test public void pausePreservesBlinkAndCalibrationButBreaksClosedTimer(){Analytics.Drive a=new Analytics.Drive();a.update(List.of(face(20,0,1)),0);a.calibrate();a.update(List.of(face(20,0,0)),100);a.update(List.of(face(20,0,1)),200);assertEquals(1,a.snapshot().blinks);a.update(List.of(face(20,0,0)),300);a.pause();Analytics.DriveSnapshot s=a.update(List.of(face(20,0,0)),3000);assertFalse(s.drowsy);assertEquals(0,s.closedMs);assertEquals(1,s.blinks);assertTrue(s.calibrated);a.resetCounts();assertEquals(0,a.snapshot().blinks);assertTrue(a.snapshot().calibrated);}
 @Test public void flowPausePreservesCountsButCannotBridgeUnseenCrossing(){Analytics.Flow a=new Analytics.Flow();a.update(List.of(person(.4f)),0);a.update(List.of(person(.6f)),100);assertEquals(1,a.snapshot().total);a.pause();a.update(List.of(person(.4f)),200);assertEquals(1,a.snapshot().total);a.update(List.of(person(.6f)),300);assertEquals(2,a.snapshot().total);}
 @Test public void visitorLongIdsDoNotNarrowOrCollide(){Analytics.Visitors a=new Analytics.Visitors();List<Observations.Face> f=List.of(face(0,0,1),face(0,0,1));long big=(long)Integer.MAX_VALUE+1;assertEquals(2,a.update(f,new long[]{big,big+(1L<<32)},0).unique);assertEquals(2,a.update(f,new long[]{big,big+(1L<<32)},100).unique);assertEquals(200,a.snapshot().totalDwellMs);}
 @Test public void visitorPauseExcludesGapAndKeepsIdentityUntilTtl(){Analytics.Visitors a=new Analytics.Visitors(1000);List<Observations.Face> f=List.of(face(0,0,1));a.update(f,new long[]{5000000000L},0);a.update(f,new long[]{5000000000L},100);a.pause();Analytics.VisitorSnapshot s=a.update(f,new long[]{5000000000L},500);assertEquals(1,s.unique);assertEquals(100,s.totalDwellMs);a.update(f,new long[]{5000000000L},600);assertEquals(200,a.snapshot().totalDwellMs);a.pause();assertEquals(2,a.update(f,new long[]{5000000000L},1700).unique);}
 @Test(expected=IllegalArgumentException.class)public void visitorRejectsMismatchedIdentityArray(){new Analytics.Visitors().update(List.of(face(0,0,1)),new long[0],0);}
}
